      SUBROUTINE RCOUT3CC     PRINTS THIRD-ORDER TRANSFER MATRICESCC ----------------------------------------------------------------------      INCLUDE 'IOUNIT.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'US.CIN'C     C     LOCAL VARIABLESC      INTEGER         J, JKM, K, M, N      REAL            OUTPUT(10)C---------------------------------------------------------------------CC     PRINT THIRD ORDER TRANSFER MATRIXC      WRITE (NOUT,1012) 1012 FORMAT (1H ,8X,'*3RD ORDER TRANSFORM*')      DO 310 N = 1, 4      JKM = 0      DO 309 J = 1, 6      DO 309 K = 1, J      DO 308 M = 1, K      JKM = JKM + 1      OUTPUT(M) = US(N,JKM)*UBEAM(J)*UBEAM(K)*UBEAM(M)/UBEAM(N)  308 CONTINUE      WRITE (NOUT,1013) (N, M, K, J, OUTPUT(M), M = 1, K) 1013 FORMAT (8X,6(I4,I2,2I1,1PE11.3))  309 CONTINUE      WRITE (NOUT,1010) 1010 FORMAT (1H )  310 CONTINUEC      RETURN      END